"""The stereo 670 (config/circuits/fairchild_670_stereo.yaml, generated by
scripts/make_fairchild_670_stereo.py; docs/STEREO_PLAN.md ST3b): both channels of drawing
A-96039 on one supply, and S301 MATRIXING. The renders run at draft-1x through
scripts/fairchild_670_stereo_study.py's measurements (its production numbers are in
reports/fairchild_670_stereo/production/summary.json); the bounds sit a few dB outside them.
"""

import dataclasses
import importlib.util

import pytest

from varimu.circuit import builder, spec
from varimu.circuit.ir import CircuitIR, Control
from varimu.config import REPO_ROOT
from varimu.preflight import check_circuit

CIRCUIT = "fairchild_670_stereo"


def _script(name: str):
    path = REPO_ROOT / "scripts" / f"{name}.py"
    sp = importlib.util.spec_from_file_location(name, path)
    mod = importlib.util.module_from_spec(sp)
    sp.loader.exec_module(mod)
    return mod


def _ir(mode: int):
    return builder.build(spec.load_circuit(spec.circuit_path(CIRCUIT)), {"mode": mode}).ir


def test_the_generated_file_is_current():
    mod = _script("make_fairchild_670_stereo")
    assert mod.OUT.read_text(encoding="utf-8").replace("\r\n", "\n") == mod.build(), (
        "rerun `uv run python scripts/make_fairchild_670_stereo.py`"
    )


def test_passes_the_preflight_checks_at_every_position():
    c = spec.load_circuit(spec.circuit_path(CIRCUIT))
    assert c.audio_inputs == (("in_r", "in_r"),)
    assert check_circuit(c) == []


def test_the_right_input_is_an_audio_control_and_round_trips():
    ir = _ir(1)
    assert ir.controls == (Control("in_r", "in_r", audio=True),)
    assert CircuitIR.from_json(ir.to_json()) == ir
    # A plain control writes no `audio` (every IR before it reads and writes as it did).
    plain = dataclasses.replace(ir, controls=(Control("in_r", "in_r"),))
    assert '"audio"' not in plain.to_json()
    assert CircuitIR.from_json(plain.to_json()) == plain


def _contacts(ir) -> set[frozenset[str]]:
    return {
        frozenset((e.a, e.b)) for s in ir.sections if s.title.startswith("S301") for e in s.elements
    }


def test_s301_wires_left_right_and_lateral_vertical_as_traced():
    # Position 1: each attenuator into its own transformer's two primaries in series, each
    # channel's two secondaries in series to its output.
    lr = _contacts(_ir(1))
    assert {
        frozenset(p)
        for p in [
            ("t101_2", "t101_3"),
            ("0", "t101_4"),
            ("pri_2", "t201_1"),
            ("t201_2", "t201_3"),
            ("t201_4", "0"),
            ("t102_7", "t102_8"),
            ("0", "t102_10"),
            ("out_r", "t202_5"),
            ("t202_8", "t202_7"),
            ("t202_10", "0"),
        ]
    } == lr
    # Position 2: L through T101's and T201's first primaries, R through their second (T201's
    # reversed); out = T102's first + T202's first, out_r = T102's second - T202's second.
    lv = _contacts(_ir(2))
    assert {
        frozenset(p)
        for p in [
            ("t101_2", "t201_1"),
            ("0", "t201_3"),
            ("pri_2", "t101_3"),
            ("t201_2", "0"),
            ("t201_4", "t101_4"),
            ("t102_7", "t202_5"),
            ("0", "t202_7"),
            ("out_r", "t102_8"),
            ("t202_8", "0"),
            ("t202_10", "t102_10"),
        ]
    } == lv


@pytest.fixture(scope="module")
def bench():
    pytest.importorskip("circuitsim", reason="needs `uv sync --extra fast`")
    return _script("fairchild_670_stereo_study").Bench("draft-1x")


@pytest.fixture(scope="module")
def study():
    return _script("fairchild_670_stereo_study")


def test_left_right_against_the_one_channel_file(bench, study):
    r = study.vs_mono(bench)
    # The one-channel file's pick-off and trims, the right silent: that file's channel 1 (its
    # lumped idle channel 2 is the rest). Measured -84.4 dB.
    assert r["mono_pickoff_left_alone_vs_mono_db"] < -75
    # Both channels driven alike: each the other's twin (-94.9 dB) ...
    assert r["mono_pickoff_both_right_vs_left_db"] < -80
    # ... and the supply's coupling the bound: both channels' 6386 current in L302 moves the
    # cathode return (nb2) twice as far, -28.1 dB from the one-channel file, +0.41 dB.
    assert -34 < r["mono_pickoff_both_vs_mono_db"] < -22
    assert 0.2 < r["gain_db"]["both"] - r["gain_db"]["mono"] < 0.7


def test_separation_in_both_positions(bench, study):
    r = study.separation(bench)
    assert r["left_right_db"] > 100  # nothing but the supply couples them ([MAN]: 60 dB)
    assert r["lateral_vertical_db"] > 100  # matched channels cancel ([MAN]: 40 dB)
    # Channels 0.2 dB apart (channel 2's 6386s 10 % hotter): the manual's 40 dB.
    assert 33 < r["lateral_vertical_unmatched_db"] < 44
    # The drawing's 180 ohm terminations across both primaries of each input transformer:
    # a source sees half the load at LATERAL & VERTICAL (measured -3.88 dB).
    assert -4.5 < r["gain_lv_vs_lr_db"] < -3.3


def test_lateral_vertical_keeps_a_centred_image_under_a_panned_peak(bench, study):
    r = study.panned(bench)
    # LEFT & RIGHT: the left ducks, the right doesn't (its supply even lifts it): the centre
    # drifts right, 6.5 dB measured.
    assert r["lr"]["image_shift_db"] > 4.5
    # LATERAL & VERTICAL: the sum and difference both limit, the centre ducks on both sides.
    assert abs(r["lv"]["image_shift_db"]) < 0.2
    assert r["lv"]["left_ducks_db"] < -1.5
